  "tablas": {"audit_log":"r | rls=true | anon=siud | columnas=bff4d69bca3c508c86b577851f650f2c","bill_uploads":"r | rls=true | anon=siud | columnas=081ebb8f0309b2346e40391c6e75bb62","blog_posts":"r | rls=true | anon=siud | columnas=20c7085eff6de00c054023ca67ad2026","brand_assets":"r | rls=true | anon=siud | columnas=20b5771c6d25cb3d52603f294fa0738f","brands":"r | rls=true | anon=iud | columnas=7de11ab19190deb693588e46391ce10d","brands_public":"v | rls=false | anon=siud | columnas=5f5c1e55029c7424035b6e974ef69cb2","calc_params":"r | rls=true | anon=siud | columnas=95909d5559c4fd0c7a71b4b5e6ecd381","company_stats":"r | rls=true | anon=siud | columnas=272502aa4292db068981a862912246ba","consents":"r | rls=true | anon=siud | columnas=d5eb297ece2d51342bb8cf50faa8989a","content_blocks":"r | rls=true | anon=siud | columnas=69ca70bfc26071695a6b892470c844f4","cron_runs":"r | rls=true | anon=siud | columnas=fc7a4a1e58fbfaf014ded5a650102e19","events":"r | rls=true | anon=siud | columnas=6b1fe61b93db8dff4ac041fc6f76360c","industrial_documents":"r | rls=true | anon=siud | columnas=456cb7cc5577248844542cb158d93cc0","industrial_requests":"r | rls=true | anon=siud | columnas=8fe0de89c87aab4e2fb4002f49a15043","lead_activities":"r | rls=true | anon=siud | columnas=e7a5c3313454bceeb9676e3f7d22af0e","leads":"r | rls=true | anon=siud | columnas=e0e11c45b32b6b177a4ed281d44ca837","media":"r | rls=true | anon=siud | columnas=f0216fd70a967a83071dc172ce1d3031","order_items":"r | rls=true | anon=siud | columnas=a7d178657bb4a38b6b4fd4c8708b0ae8","order_status_history":"r | rls=true | anon=siud | columnas=85b4214a0d6d7ed795721fb56f649399","orders":"r | rls=true | anon=siud | columnas=29c56bc6bbd5423d7a6be7c68cc31d46","outbound_messages":"r | rls=true | anon=siud | columnas=d5171e90be4a8ee9cbf5af318ed57bab","product_categories":"r | rls=true | anon=siud | columnas=141946508c2872b9781dd9e9cb2d10db","product_prices":"r | rls=true | anon=siud | columnas=946d092e2721432a62b9f9de4d05bd02","product_relations":"r | rls=true | anon=siud | columnas=aa726fb97a20626de870f6afab0ebb40","products":"r | rls=true | anon=siud | columnas=f709d2fd0278b72d76ea2b501ca185a5","profiles":"r | rls=true | anon=siud | columnas=49b79b29d5c60e0d2fc0d22a0a477b13","project_media":"r | rls=true | anon=siud | columnas=c9275e58a6633bc214c8acf99ee055d7","projects":"r | rls=true | anon=iud | columnas=a871a677001e04e3b33339622277d4bc","projects_public":"v | rls=false | anon=siud | columnas=8480b6bab042eb3c8018a787703e63e0","rate_limits":"r | rls=true | anon=siud | columnas=6fc3f7363e6dd8e3f63995b70834762f","seo_meta":"r | rls=true | anon=siud | columnas=5f63f70507032ebc965e8c494ddfa21d","services":"r | rls=true | anon=siud | columnas=1e34a3f07508af50b5ef9bf0e5b16758","site_settings":"r | rls=true | anon=siud | columnas=20b5dd3ee91e0ef24c06e7b7602394b5","solar_resource_cache":"r | rls=true | anon=siud | columnas=2702f1bf7aa9b78f0e7f398803613386","solar_studies":"r | rls=true | anon=siud | columnas=f2b0a376f347c36712fb74e55eaae669","tariffs":"r | rls=true | anon=siud | columnas=635ce82a88cbae10680926e2358177d3","trade_accounts":"r | rls=true | anon=siud | columnas=c6165ad3488fae5d9bd58daf2c91b739"},
  "tipos": {"app_role":"superadmin, gerencia, marketing, ventas, ingenieria, compras","lead_source":"calculadora, tienda, contacto, cotizacion, catalogo, financiamiento, capacitacion, campana, servicio, cuenta_comercial, cotizacion_industrial","lead_stage":"nuevo, contactado, calificado, visita_tecnica, cotizacion_enviada, negociacion, ganado, perdido","order_status":"nuevo, pendiente_contacto, contactado, cotizado, confirmado, pagado, en_preparacion, despachado, entregado, cancelado","price_tier":"final, instalador, distribuidor","project_status":"en_desarrollo, en_construccion, operativo, finalizado","segment":"residencial, comercial, industrial"}
}'::jsonb as j),
funcs as (
  select p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' as firma, md5(replace(pg_get_functiondef(p.oid), chr(13) || chr(10), chr(10)))
        || ' | propietario=' || pg_get_userbyid(p.proowner)
        || ' | ejecutan=' || concat_ws(',',
          case when exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE') then 'PUBLIC' end,
          case when has_function_privilege('anon', p.oid, 'execute') then 'anon' end,
          case when has_function_privilege('authenticated', p.oid, 'execute') then 'authenticated' end,
          case when has_function_privilege('service_role', p.oid, 'execute') then 'service_role' end) as valor, p.prosecdef, pg_get_userbyid(p.proowner) as owner,
    coalesce(array_to_string(p.proconfig, ', '), '') as config, p.prorettype::regtype::text as retorna
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.prokind in ('f', 'p')
        and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')),
comparado as (
  select coalesce(f.firma, x.firma) as firma, f.valor, f.prosecdef, f.owner, f.config, f.retorna, x.esperado_valor, o.opcional_valor
  from funcs f
  full join (select key as firma, value #>> '{}' as esperado_valor from esperado, jsonb_each(j -> 'funciones')) x on x.firma = f.firma
  left join (select key as firma, value #>> '{}' as opcional_valor from esperado, jsonb_each(j -> 'opcionales' -> 'funciones')) o on o.firma = coalesce(f.firma, x.firma)),
filas(seccion, orden, objeto, estado, esperado, actual, detalle) as (
  select '1 servidor', 1, 'postgres', '', '', current_setting('server_version'), version()
  union all
  select '2 funcion', 2, firma,
    case when valor is null then 'FALTA'
         when esperado_valor = valor then 'igual'
         when esperado_valor is null and opcional_valor = valor then 'de Supabase (revisada)'
         when esperado_valor is null then 'SOBRA'
         else 'DISTINTA' end,
    coalesce(split_part(coalesce(esperado_valor, opcional_valor), ' | ', 3), ''),
    coalesce(split_part(valor, ' | ', 3), ''),
    case when valor is null then 'no existe' else 'propietario=' || owner || ' · SECURITY ' || case when prosecdef then 'DEFINER' else 'INVOKER' end
      || ' · retorna ' || retorna || ' · config=[' || config || ']'
      || case when esperado_valor is not null and split_part(esperado_valor, ' | ', 1) <> split_part(valor, ' | ', 1) then ' · DEFINICIÓN DISTINTA' else '' end end
  from comparado
  union all
  select '3 invocacion', 3, split_part(x, '|', 1) || ' → ' || split_part(x, '|', 2), split_part(x, '|', 3), 'denegado', split_part(x, '|', 3), ''
  from unnest(string_to_array(nullif(current_setting('ese.diag_invocacion', true), ''), ';')) x
  union all
  select '4 supabase', 4, 'ensure_rls',
    case when (select e.evtevent || ' | ' || e.evtfoid::regprocedure::text || ' | activo=' || (e.evtenabled::text <> 'D')
        || ' | ' || coalesce(array_to_string(e.evttags, ', '), 'todas') || ' | propietario=' || pg_get_userbyid(e.evtowner)
      from pg_event_trigger e where e.evtname = 'ensure_rls') is null then 'no instalado'
         when (select e.evtevent || ' | ' || e.evtfoid::regprocedure::text || ' | activo=' || (e.evtenabled::text <> 'D')
        || ' | ' || coalesce(array_to_string(e.evttags, ', '), 'todas') || ' | propietario=' || pg_get_userbyid(e.evtowner)
      from pg_event_trigger e where e.evtname = 'ensure_rls') = e.j -> 'opcionales' ->> 'ensure_rls' then 'igual a la versión revisada' else 'DISTINTO' end,
    e.j -> 'opcionales' ->> 'ensure_rls', coalesce((select e.evtevent || ' | ' || e.evtfoid::regprocedure::text || ' | activo=' || (e.evtenabled::text <> 'D')
        || ' | ' || coalesce(array_to_string(e.evttags, ', '), 'todas') || ' | propietario=' || pg_get_userbyid(e.evtowner)
      from pg_event_trigger e where e.evtname = 'ensure_rls'), ''), ''
  from esperado e),
resumen as (
  select count(*) filter (where (seccion = '2 funcion' and estado not in ('igual', 'de Supabase (revisada)'))
    or (seccion = '3 invocacion' and estado <> 'denegado') or (seccion = '4 supabase' and estado = 'DISTINTO')) as problemas,
    count(*) filter (where seccion = '3 invocacion') as invocaciones
  from filas)
select '0 resumen' as seccion, case when problemas = 0 and invocaciones = 12 then 'todo coincide con lo probado' else 'REVISAR: ' || problemas || ' problema(s)' end as objeto,
  case when problemas = 0 and invocaciones = 12 then '✓' else '✗' end as estado, '' as esperado, '' as actual,
  invocaciones || ' invocaciones simuladas (esperadas 12)' as detalle
from resumen
union all
select seccion, objeto, estado, esperado, actual, detalle from filas
order by 1, 2;
